<?php
$page_title = 'Payment Receipt'; require_once __DIR__ . '/header.php';
$q = db()->prepare('SELECT p.*, s.category, s.service_item FROM payments p LEFT JOIN services s ON p.service_id=s.id WHERE p.id=?'); $q->execute([(int)($_GET['id'] ?? 0)]); $p = $q->fetch();
if (!$p) { flash('Payment receipt not found.', 'error'); header('Location: records.php'); exit; }
